files.parse.go:
package vectors

// Parse splits a header line.
func Parse(line string) []string {
	if line == "" {
		return nil // CVX-001
	}
	return strings.Fields(line)
}

files.render.go:
package vectors

// Render writes one line per record: CVX-002
func Render(records ...string) string {
	return strings.Join(records, "\n")
}
